import{_ as o,C as s,o as t,c as n,a2 as r,b as l,w as i,a as d,E as c,a3 as g}from"./chunks/framework.Dd_iHz3e.js";const S=JSON.parse('{"title":"14.14 Observability, Logging & Site Reliability Operations","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/14.14-observability-and-operations.md","filePath":"system-design/14.14-observability-and-operations.md"}'),h={name:"system-design/14.14-observability-and-operations.md"};function u(p,e,m,b,f,v){const a=s("Mermaid");return t(),n("div",null,[e[1]||(e[1]=r('<h1 id="_14-14-observability-logging-site-reliability-operations" tabindex="-1">14.14 Observability, Logging &amp; Site Reliability Operations <a class="header-anchor" href="#_14-14-observability-logging-site-reliability-operations" aria-label="Permalink to &quot;14.14 Observability, Logging &amp; Site Reliability Operations&quot;">​</a></h1><h2 id="_1-plain-english-overview" tabindex="-1">1. Plain English Overview <a class="header-anchor" href="#_1-plain-english-overview" aria-label="Permalink to &quot;1. Plain English Overview&quot;">​</a></h2><p>Observability provides deep, real-time visibility into an application&#39;s internal state through the &quot;Three Pillars of Observability&quot;—Logs, Metrics, and Distributed Traces—allowing engineers to detect anomalies, debug outages, and ensure high system reliability.</p><hr><h2 id="_2-usage-in-cooking-nexus" tabindex="-1">2. Usage in Cooking Nexus <a class="header-anchor" href="#_2-usage-in-cooking-nexus" aria-label="Permalink to &quot;2. Usage in Cooking Nexus&quot;">​</a></h2><ul><li><strong>Current Logging</strong>: Express console logging for magic link generation and server startup ([server.js:L6](file:///Users/avishjain/avishjain9-repos/26-cooking-nexus/server.js#L6), [authController.js:L12](file:///Users/avishjain/avishjain9-repos/26-cooking-nexus/controllers/authController.js#L12)).</li><li><strong>Safety Incident Audits</strong>: <code>SafetyLog</code> collection preserving historical hazard records.</li><li><strong>Client Error Boundary</strong>: Toast notification interceptors catching SSE streaming failures in [ai-stream.ts:L95](file:///Users/avishjain/avishjain9-repos/26-cooking-nexus/27-kitchen-companion-pro/src/lib/ai-stream.ts#L95).</li></ul><hr><h2 id="_3-observability-architecture-the-3-pillars" tabindex="-1">3. Observability Architecture (The 3 Pillars) <a class="header-anchor" href="#_3-observability-architecture-the-3-pillars" aria-label="Permalink to &quot;3. Observability Architecture (The 3 Pillars)&quot;">​</a></h2>',8)),(t(),l(g,null,{default:i(()=>[c(a,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20subgraph%20ExpressNode%20%5B%22Node.js%20Express%20App%22%5D%0A%20%20%20%20%20%20%20%20Req%5BIncoming%20HTTP%20Request%5D%20--%3E%20Correlation%5BAssign%20x-correlation-id%5D%0A%20%20%20%20%20%20%20%20Correlation%20--%3E%20PinoLog%5BPino%20Structured%20JSON%20Logger%5D%0A%20%20%20%20%20%20%20%20Correlation%20--%3E%20PromMetric%5Bprom-client%20Prometheus%20Metrics%5D%0A%20%20%20%20%20%20%20%20Correlation%20--%3E%20OTelTrace%5BOpenTelemetry%20Distributed%20Tracing%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20ObservabilityPlatform%20%5B%22Unified%20Observability%20Stack%22%5D%0A%20%20%20%20%20%20%20%20PinoLog%20--%3E%7CLog%20Shipper%20(Vector)%7C%20Loki%5BGrafana%20Loki%20%2F%20Datadog%20Logs%5D%0A%20%20%20%20%20%20%20%20PromMetric%20--%3E%7CPull%20%2Fmetrics%20%3A9090%7C%20Prometheus%5BPrometheus%20Server%5D%0A%20%20%20%20%20%20%20%20OTelTrace%20--%3E%7CgRPC%20OTLP%7C%20Tempo%5BGrafana%20Tempo%20%2F%20Jaeger%20Traces%5D%0A%20%20%20%20end%0A%0A%20%20%20%20Prometheus%20%26%20Loki%20%26%20Tempo%20--%3E%20GrafanaDashboard%5B%22Unified%20Grafana%20Dashboard%20%26%20PagerDuty%20Alerts%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<hr><h2 id="_4-observability-tools-comparison" tabindex="-1">4. Observability Tools Comparison <a class="header-anchor" href="#_4-observability-tools-comparison" aria-label="Permalink to &quot;4. Observability Tools Comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool / Category</th><th>Primary Pillar</th><th>Overhead</th><th>Scalability</th><th>Cost Profile</th><th>Fit for Cooking Nexus</th></tr></thead><tbody><tr><td><strong>Pino (Recommended)</strong></td><td>Structured Logs</td><td>Ultra-Low (Fastest JSON)</td><td>High</td><td>Open Source</td><td>Standard for Node backend</td></tr><tr><td><strong>Winston</strong></td><td>Logs</td><td>Moderate (Transport tax)</td><td>Moderate</td><td>Open Source</td><td>Popular, but slower than Pino</td></tr><tr><td><strong>Prometheus + Grafana</strong></td><td>Metrics (Time-series)</td><td>Low (Pull model)</td><td>High (Mimir / Cortex)</td><td>Open Source / Low cost</td><td>Industry standard</td></tr><tr><td><strong>OpenTelemetry (OTel)</strong></td><td>Distributed Tracing</td><td>Low</td><td>Vendor-neutral</td><td>Open Source</td><td>Essential for microservices</td></tr><tr><td><strong>Datadog / Sentry</strong></td><td>Full-Stack APM &amp; Errors</td><td>Ultra-Low (Agent based)</td><td>SaaS Scale</td><td>High ($$$ per host)</td><td>Great for automated crash alerts</td></tr></tbody></table><hr><h2 id="_5-golden-signals-sli-slo-definitions" tabindex="-1">5. Golden Signals &amp; SLI / SLO Definitions <a class="header-anchor" href="#_5-golden-signals-sli-slo-definitions" aria-label="Permalink to &quot;5. Golden Signals &amp; SLI / SLO Definitions&quot;">​</a></h2><ul><li><strong>Service Level Indicator (SLI)</strong>: <ol><li><em>Availability</em>: Percentage of successful HTTP 200/202 responses on <code>/api/vision</code>.</li><li><em>Latency</em>: 99th percentile (p99) response time for hazard ingestion.</li></ol></li><li><strong>Service Level Objective (SLO)</strong>: <ol><li>99.9% of <code>/api/vision</code> requests complete successfully over any rolling 30-day window.</li><li>95% of requests complete in $&lt; 100\\text{ms}$.</li></ol></li><li><strong>Service Level Agreement (SLA)</strong>: 99.5% uptime commitment to smart kitchen appliance manufacturers.</li></ul><hr><h2 id="_6-what-breaks-first-at-scale" tabindex="-1">6. What Breaks First at Scale? <a class="header-anchor" href="#_6-what-breaks-first-at-scale" aria-label="Permalink to &quot;6. What Breaks First at Scale?&quot;">​</a></h2><ul><li><strong>At 10x</strong>: Server disk space fills up with un-rotated <code>console.log</code> stdout text files.</li><li><strong>At 100x</strong>: Alert fatigue: poorly tuned alerts wake on-call engineers for benign 1-second transient network blips.</li><li><strong>At 1,000x</strong>: High-cardinality metric explosion in Prometheus if tracking metrics with dynamic user IDs as labels.</li></ul><hr><h2 id="_7-senior-engineer-improvements" tabindex="-1">7. Senior Engineer Improvements <a class="header-anchor" href="#_7-senior-engineer-improvements" aria-label="Permalink to &quot;7. Senior Engineer Improvements&quot;">​</a></h2><ol><li><strong>Correlation IDs</strong>: Inject an <code>x-correlation-id</code> header in Express middleware. Pass this ID into every database query, log message, and upstream AI request so an engineer can trace an entire request across all services with a single search.</li><li><strong>Crash Reporting</strong>: Integrate <strong>Sentry</strong> in both the React frontend and Express backend to capture unhandled exceptions with full stack traces and client breadcrumbs.</li></ol><hr><h2 id="_8-spoken-interview-answer-30-seconds" tabindex="-1">8. Spoken Interview Answer (30 Seconds) <a class="header-anchor" href="#_8-spoken-interview-answer-30-seconds" aria-label="Permalink to &quot;8. Spoken Interview Answer (30 Seconds)&quot;">​</a></h2><p>&quot;In Cooking Nexus, our observability strategy focuses on the four Golden Signals: Latency, Traffic, Errors, and Saturation. We use Pino for high-performance structured JSON logging with correlation IDs, Prometheus for tracking request duration percentiles, and Sentry for real-time frontend crash alerts. By setting our SLO to 99.9% availability for kitchen safety ingestion, our alerting rules page engineers only when burn rates threaten customer-facing reliability.&quot;</p>',15))])}const _=o(h,[["render",u]]);export{S as __pageData,_ as default};
